90: FAACAPI faac_status faac_params_init(faac_params *p)
91: {
92:     if (!p)
93:         return FAAC_ERR_INVALID_ARGUMENT;
94: 
95:     memset(p, 0, sizeof(*p));
96:     p->struct_size   = (uint32_t)sizeof(faac_params);
97:     p->mpeg_version  = FAAC_MPEG4;
98:     p->object_type   = FAAC_OBJ_LOW;
99:     p->joint_mode    = FAAC_JOINT_MIXED;
100:     p->use_lfe       = false;
101:     p->use_tns       = false;
102:     p->bit_rate      = 64000;          /* per channel; 0 would defer to quant_quality */
103:     p->bandwidth     = 0;              /* derive from bit_rate */
104:     p->quant_quality = 0;              /* derive from bit_rate */
105:     p->output_format = FAAC_STREAM_ADTS;
106:     p->input_format  = FAAC_INPUT_16BIT;
107:     p->short_control = FAAC_SHORTCTL_NORMAL;
108:     p->pns_level     = 4;
109:     return FAAC_OK;
