112: /* Validate the enumerated/range fields the caller supplied. Returns FAAC_OK,
113:  * FAAC_ERR_INVALID_ARGUMENT for out-of-range values, or FAAC_ERR_UNSUPPORTED
114:  * for values that are valid but not implemented in this build. */
115: static faac_status validate_params(const faac_params *p)
116: {
117:     switch (p->mpeg_version) {
118:         case FAAC_MPEG4: case FAAC_MPEG2: break;
119:         default: return FAAC_ERR_INVALID_ARGUMENT;
120:     }
121:     switch (p->object_type) {
122:         case FAAC_OBJ_AUTO: case FAAC_OBJ_LOW: case FAAC_OBJ_HE_AAC_V1:
123:             break;
124:         case FAAC_OBJ_HE_AAC_V2:
125:             return FAAC_ERR_UNSUPPORTED;   /* parametric stereo not implemented */
126:         default:
127:             return FAAC_ERR_INVALID_ARGUMENT;
128:     }
129:     switch (p->joint_mode) {
130:         case FAAC_JOINT_NONE: case FAAC_JOINT_MS:
131:         case FAAC_JOINT_IS:   case FAAC_JOINT_MIXED: break;
132:         default: return FAAC_ERR_INVALID_ARGUMENT;
133:     }
134:     switch (p->short_control) {
135:         case FAAC_SHORTCTL_NORMAL: case FAAC_SHORTCTL_NOSHORT:
136:         case FAAC_SHORTCTL_NOLONG: break;
137:         default: return FAAC_ERR_INVALID_ARGUMENT;
138:     }
139:     switch (p->output_format) {
140:         case FAAC_STREAM_RAW: case FAAC_STREAM_ADTS: break;
141:         default: return FAAC_ERR_INVALID_ARGUMENT;
142:     }
143:     switch (p->input_format) {
144:         case FAAC_INPUT_16BIT: case FAAC_INPUT_32BIT: case FAAC_INPUT_FLOAT:
145:             break;
146:         case FAAC_INPUT_24BIT:
147:             return FAAC_ERR_UNSUPPORTED;   /* 24-in-24 not implemented */
148:         default:
149:             return FAAC_ERR_INVALID_ARGUMENT;
150:     }
151:     if (p->sample_rate == 0)
152:         return FAAC_ERR_INVALID_ARGUMENT;
153:     if (p->num_channels < 1 || p->num_channels > (uint32_t)MAX_CHANNELS)
154:         return FAAC_ERR_INVALID_ARGUMENT;
155:     if (p->pns_level < 0 || p->pns_level > 10)
156:         return FAAC_ERR_INVALID_ARGUMENT;
157:     if (p->channel_map) {
158:         uint32_t i;
159:         if (p->channel_map_count < p->num_channels)
160:             return FAAC_ERR_INVALID_ARGUMENT;
161:         for (i = 0; i < p->num_channels; i++)
162:             if (p->channel_map[i] < 0 || (uint32_t)p->channel_map[i] >= p->num_channels)
163:                 return FAAC_ERR_INVALID_ARGUMENT;
164:     }
165:     /* reserved padding must be zero so future fields can claim it safely */
166:     if (p->reserved[0] || p->reserved[1] || p->reserved_trailing)
167:         return FAAC_ERR_INVALID_ARGUMENT;
168:     return FAAC_OK;
169: }
