171: FAACAPI faac_status faac_encoder_open(const faac_params *p, faac_encoder **out)
172: {
173:     faacEncStruct *h;
174:     faacEncConfiguration *cfg;
175:     unsigned long inSamples = 0, maxOut = 0;
176:     faac_status st;
177: 
178:     if (!out)
179:         return FAAC_ERR_INVALID_ARGUMENT;
180:     *out = NULL;
181:     if (!p)
182:         return FAAC_ERR_INVALID_ARGUMENT;
183: 
184:     /* struct_size lets the library reconcile a caller compiled against a
185:      * different header revision. A caller must be at least as new as this
186:      * build's struct (older/garbage/zero is rejected); newer callers are read
187:      * only through the fields this build knows. */
188:     if (p->struct_size < sizeof(faac_params))
189:         return FAAC_ERR_INVALID_ARGUMENT;
190: 
191:     st = validate_params(p);
192:     if (st != FAAC_OK)
193:         return st;
194: 
195:     h = (faacEncStruct *)faacEncOpen(p->sample_rate, p->num_channels,
196:                                      &inSamples, &maxOut);
197:     if (!h)
198:         return FAAC_ERR_NO_MEMORY;
199: 
200:     /* Translate params onto the handle's own configuration and run it through
201:      * the shared core validation/derivation in faacEncApplyConfig. */
202:     cfg = &h->config;
203:     cfg->mpegVersion   = (unsigned int)p->mpeg_version;
204:     cfg->aacObjectType = (unsigned int)p->object_type;  /* LOW / HE_V1 / AUTO */
205:     cfg->jointmode     = (unsigned int)p->joint_mode;
206:     cfg->useLfe        = p->use_lfe ? 1 : 0;
207:     cfg->useTns        = p->use_tns ? 1 : 0;
208:     cfg->bitRate       = p->bit_rate;
209:     cfg->bandWidth     = p->bandwidth;
210:     cfg->quantqual     = p->quant_quality;
211:     cfg->outputFormat  = (unsigned int)p->output_format;
212:     cfg->inputFormat   = (unsigned int)p->input_format;
213:     cfg->shortctl      = (int)p->short_control;
214:     cfg->pnslevel      = p->pns_level;
215:     if (p->channel_map) {
216:         uint32_t i;
217:         for (i = 0; i < p->num_channels; i++)
218:             cfg->channel_map[i] = p->channel_map[i];
219:     }
220:     /* else: faacEncOpen already installed the identity map */
221: 
222:     if (!faacEncApplyConfig(h, cfg)) {
223:         faacEncClose((faacEncHandle)h);
224:         return FAAC_ERR_INVALID_ARGUMENT;
225:     }
226: 
227:     *out = (faac_encoder *)h;
228:     return FAAC_OK;
229: }
