231: FAACAPI faac_status faac_encoder_close(faac_encoder **enc)
232: {
233:     if (!enc)
234:         return FAAC_ERR_INVALID_ARGUMENT;
235:     if (*enc) {
236:         faacEncClose((faacEncHandle)unwrap(*enc));
237:         *enc = NULL;
238:     }
239:     return FAAC_OK;
240: }
