242: FAACAPI faac_status faac_encoder_get_info(faac_encoder *enc, faac_encoder_info *out)
243: {
244:     faac_encoder_info info;
245:     faacEncStruct *h;
246:     uint32_t caller_size, n;
247: 
248:     if (!enc || !out)
249:         return FAAC_ERR_INVALID_ARGUMENT;
250:     caller_size = out->struct_size;
251:     if (caller_size < sizeof(info.struct_size))
252:         return FAAC_ERR_INVALID_ARGUMENT;
253:     h = unwrap(enc);
254: 
255:     memset(&info, 0, sizeof(info));
256:     info.frame_samples    = faacFrameSamples(h);
257:     info.max_output_bytes = (uint32_t)ADTS_FRAMESIZE;
258:     /* The handle holds the halved core rate for HE-AAC; report the rate the
259:      * decoder reconstructs. */
260:     info.sample_rate      = (uint32_t)SbrContextGetFullRate(h->sbrContext, h->sampleRate);
261:     info.object_type      = (enum faac_object_type)h->config.aacObjectType;
262:     info.bit_rate         = (uint32_t)h->config.bitRate;
263:     info.bandwidth        = (uint32_t)h->config.bandWidth;
264:     info.quant_quality    = (uint32_t)h->config.quantqual;
265:     info.pns_level        = (int32_t)h->config.pnslevel;
266: 
267:     /* Write at most the caller's struct_size so a newer library cannot overrun
268:      * an older, smaller faac_encoder_info; report the byte count actually set. */
269:     n = caller_size < (uint32_t)sizeof(info) ? caller_size : (uint32_t)sizeof(info);
270:     info.struct_size = n;
271:     memcpy(out, &info, n);
272:     return FAAC_OK;
273: }
