275: FAACAPI faac_status faac_encoder_asc(faac_encoder *enc,
276:                                      const uint8_t **buf, uint32_t *len)
277: {
278:     faacEncStruct *h;
279: 
280:     if (!enc || !buf || !len)
281:         return FAAC_ERR_INVALID_ARGUMENT;
282:     h = unwrap(enc);
283: 
284:     if (!h->ascCache) {
285:         int rc = faacEncGetDecoderSpecificInfo((faacEncHandle)h,
286:                                                &h->ascCache, &h->ascCacheLen);
287:         if (rc != 0) {
288:             h->ascCache = NULL;
289:             h->ascCacheLen = 0;
290:             /* -2 is "MPEG-2 has no ASC"; everything else is an allocation or
291:              * argument failure. */
292:             return (rc == -2) ? FAAC_ERR_UNSUPPORTED : FAAC_ERR_NO_MEMORY;
293:         }
294:     }
295: 
296:     *buf = h->ascCache;
297:     *len = (uint32_t)h->ascCacheLen;
298:     return FAAC_OK;
299: }
300: 
301: FAACAPI faac_status faac_encoder_encode(faac_encoder *enc,
302:                                         const void *in, uint32_t in_samples,
303:                                         uint8_t *out, uint32_t out_cap,
304:                                         uint32_t *bytes_written)
305: {
306:     faacEncStruct *h;
307:     int rc;
308: 
309:     if (!enc || !out || !bytes_written)
310:         return FAAC_ERR_INVALID_ARGUMENT;
311:     *bytes_written = 0;
312:     if (in_samples && !in)
313:         return FAAC_ERR_INVALID_ARGUMENT;
314:     h = unwrap(enc);
315: 
316:     if (out_cap < (uint32_t)ADTS_FRAMESIZE)
317:         return FAAC_ERR_OUTPUT_TOO_SMALL;
318:     if (in_samples > faacFrameSamples(h) * h->numChannels)
319:         return FAAC_ERR_INPUT_OVERFLOW;
320: 
321:     /* faacEncEncode reinterprets the input bytes per the configured
322:      * input_format; the int32_t* parameter is historical and does not imply an
323:      * int32 layout. */
324:     rc = faacEncEncode((faacEncHandle)h, (int32_t *)(uintptr_t)in,
325:                        in_samples, out, out_cap);
326:     /* A too-small output buffer was already rejected above, so a negative
327:      * return here is an unexpected core fault, not a buffer-size problem --
328:      * don't disguise it as one or the caller will grow the buffer and retry. */
329:     if (rc < 0)
330:         return FAAC_ERR_INTERNAL;
331: 
332:     *bytes_written = (uint32_t)rc;
333:     return FAAC_OK;
334: }
