336: FAACAPI const char *faac_strerror(faac_status status)
337: {
338:     switch (status) {
339:         case FAAC_OK:                   return "success";
340:         case FAAC_ERR_INVALID_ARGUMENT: return "invalid argument";
341:         case FAAC_ERR_UNSUPPORTED:      return "unsupported configuration";
342:         case FAAC_ERR_NO_MEMORY:        return "out of memory";
343:         case FAAC_ERR_OUTPUT_TOO_SMALL: return "output buffer too small";
344:         case FAAC_ERR_INPUT_OVERFLOW:   return "input sample count too large";
345:         case FAAC_ERR_INTERNAL:         return "internal encoder error";
346:         case FAAC_STATUS_MAX:           break;
347:     }
348:     return "unknown error";
349: }

