24: void quantize_sse2(const float * __restrict xr, int * __restrict xi, int n, float sfacfix)
25: {
26:     const __m128 zero = _mm_setzero_ps();
27:     const __m128 sfac = _mm_set1_ps(sfacfix);
28:     const __m128 magic = _mm_set1_ps(MAGIC_NUMBER);
29:     // Mask to strip the sign bit (0x7FFFFFFF)
30:     const __m128 abs_mask = _mm_castsi128_ps(_mm_set1_epi32(0x7FFFFFFF));
31:     int cnt = 0;
32: 
33:     // Process 4 elements per iteration
34:     for (; cnt <= n - 4; cnt += 4)
35:     {
36:         __m128 x_orig = _mm_loadu_ps((const float*)&xr[cnt]);
37:         // Capture sign and Absolute value
38:         __m128 sign_mask = _mm_cmplt_ps(x_orig, zero);
39:         __m128 x = _mm_and_ps(x_orig, abs_mask);
40: 
41:         // Math: (x * sfac)^0.75 + magic
42:         // Logic: sqrt( (x*sfac) * sqrt(x*sfac) )
43:         x = _mm_mul_ps(x, sfac);
44:         x = _mm_mul_ps(x, _mm_sqrt_ps(x));
45:         x = _mm_sqrt_ps(x);
46:         x = _mm_add_ps(x, magic);
47: 
48:         // Convert to integer
49:         __m128i xi_vec = _mm_cvttps_epi32(x);
50: 
