338: static int *mkChanMap(int channels, int center, int lf)
339: {
340:     int *map;
341:     int inpos;
342:     int outpos;
343: 
344:     if (!center && !lf)
345:         return NULL;
346: 
347:     if (channels < 3)
348:         return NULL;
349: 
350:     if (lf > 0)
351:         lf--;
352:     else
353:         lf = channels - 1;      // default AAC position
354: 
355:     if (center > 0)
356:         center--;
357:     else
358:         center = 0;             // default AAC position
359: 
360:     map = malloc(channels * sizeof(map[0]));
361:     if (!map) return NULL;
362:     memset(map, 0, channels * sizeof(map[0]));
363: 
364:     outpos = 0;
365:     if ((center >= 0) && (center < channels))
366:         map[outpos++] = center;
367: 
368:     inpos = 0;
369:     for (; outpos < (channels - 1) && inpos < channels; inpos++)
370:     {
371:         if (inpos == center)
372:             continue;
373:         if (inpos == lf)
374:             continue;
375: 
376:         map[outpos++] = inpos;
377:     }
378:     if (outpos < channels)
379:     {
380:         if ((lf >= 0) && (lf < channels))
381:             map[outpos] = lf;
382:         else if (inpos < channels)
383:             map[outpos] = inpos;
384:     }
385: 
386:     return map;
387: }
