489:         static struct option long_options[] = {
490:             {"help", 0, 0, 'h'},
491:             {"help-qual", 0, 0, HELP_QUAL},
492:             {"help-io", 0, 0, HELP_IO},
493:             {"help-mp4", 0, 0, HELP_MP4},
494:             {"help-advanced", 0, 0, HELP_ADVANCED},
495:             {"raw", 0, 0, 'r'},
496:             {"joint", required_argument, 0, OPT_JOINT},
497:             {"pns", required_argument, 0, OPT_PNS},
498:             {"cutoff", 1, 0, 'c'},
499:             {"quality", 1, 0, 'q'},
500:             {"pcmraw", 0, 0, 'P'},
501:             {"pcmsamplerate", 1, 0, 'R'},
502:             {"pcmsamplebits", 1, 0, 'B'},
503:             {"pcmchannels", 1, 0, 'C'},
504:             {"shortctl", 1, 0, SHORTCTL_FLAG},
505:             {"tns", 0, &useTns, 1},
506:             {"no-tns", 0, &useTns, 0},
507:             {"mpeg-version", 1, 0, MPEGVERS_FLAG},
508:             {"object-type", 1, 0, OBJTYPE_FLAG},
509:             {"license", 0, 0, 'L'},
510:             {"createmp4", 0, 0, 'w'},
511:             {"artist", 1, 0, ARTIST_FLAG},
512:             {"artistsort", 1, 0, ARTIST_SORT_FLAG},
513:             {"title", 1, 0, TITLE_FLAG},
514:             {"album", 1, 0, ALBUM_FLAG},
515:             {"albumartist", 1, 0, ALBUM_ARTIST_FLAG},
516:             {"albumartistsort", 1, 0, ALBUM_ARTIST_SORT_FLAG},
517:             {"albumsort", 1, 0, ALBUM_SORT_FLAG},
518:             {"track", 1, 0, TRACK_FLAG},
519:             {"disc", 1, 0, DISC_FLAG},
520:             {"genre", 1, 0, GENRE_FLAG},
521:             {"year", 1, 0, YEAR_FLAG},
522:             {"cover-art", 1, 0, COVER_ART_FLAG},
523:             {"comment", 1, 0, COMMENT_FLAG},
524:             {"composer", 1, 0, WRITER_FLAG},
525:             {"composersort", 1, 0, WRITER_SORT_FLAG},
526:             {"compilation", 0, &compilation, 1},
527:             {"pcmswapbytes", 0, 0, 'X'},
528:             {"ignorelength", 0, &ignorelen, 1},
529:             {"tag", 1, 0, TAG_FLAG},
530:             {"overwrite", 0, &overwrite, 1},
531:             {"creation-time", 1, 0, CREATION_TIME_FLAG},
532:             {0, 0, 0, 0}
