572:                     cutOff = i;
573:                 }
574:                 break;
575:             }
576:         case 'b':
577:             {
578:                 unsigned int i;
579:                 if (sscanf(optarg, "%u", &i) > 0)
580:                 {
581:                     bitRate = 1000 * i;
582:                 }
583:                 break;
584:             }
585:         case 'q':
586:             {
587:                 unsigned int i;
588:                 if (sscanf(optarg, "%u", &i) > 0)
