601:         case 'R':
602:             {
603:                 unsigned int i;
604:                 if (sscanf(optarg, "%u", &i) > 0)
605:                 {
606:                     rawRate = i;
607:                     rawChans = (rawChans > 0) ? rawChans : 2;
608:                 }
609:                 break;
610:             }
611:         case 'B':
612:             {
613:                 unsigned int i;
614:                 if (sscanf(optarg, "%u", &i) > 0)
615:                 {
616:                     if (i > 32)
617:                         i = 32;
618:                     if (i < 8)
619:                         i = 8;
620:                     rawBits = i;
621:                     rawChans = (rawChans > 0) ? rawChans : 2;
622:                 }
623:                 break;
624:             }
625:         case 'C':
626:             {
627:                 unsigned int i;
628:                 if (sscanf(optarg, "%u", &i) > 0)
629:                     rawChans = i;
630:                 break;
631:             }
632:         case 'w':
633:             container = MP4_CONTAINER;
634:             break;
635:         case ARTIST_FLAG:
636:             artist = optarg;
637:             break;
638:         case ARTIST_SORT_FLAG:
639:             artistsort = optarg;
640:             break;
641:         case WRITER_FLAG:
642:             composer = optarg;
643:             break;
644:         case WRITER_SORT_FLAG:
645:             composersort = optarg;
646:             break;
647:         case TITLE_FLAG:
648:             title = optarg;
649:             break;
650:         case ALBUM_FLAG:
651:             album = optarg;
652:             break;
653:         case ALBUM_ARTIST_FLAG:
654:             albumartist = optarg;
655:             break;
656:         case ALBUM_ARTIST_SORT_FLAG:
657:             albumartistsort = optarg;
658:             break;
659:         case ALBUM_SORT_FLAG:
660:             albumsort = optarg;
661:             break;
662:         case TRACK_FLAG:
