674:             genre++;
675:             break;
676:         case YEAR_FLAG:
677:             year = optarg;
678:             break;
679:         case COMMENT_FLAG:
680:             comment = optarg;
681:             break;
682:         case TAG_FLAG:
683:             tagname = optarg;
684:             if (!(tagval = strchr(optarg, ',')))
