704: 
705:                     artData = malloc(artSize);
706:                     if (!artData)
707:                     {
708:                         fprintf(stderr, "out of memory\n");
709:                         fclose(artFile);
710:                         return 1;
711:                     }
712: 
713:                     fseek(artFile, 0, SEEK_SET);
714:                     clearerr(artFile);
715: 
716:                     r = fread(artData, artSize, 1, artFile);
717: 
718:                     if (r != 1)
719:                     {
720:                         dieMessage = "Error reading cover art file!\n";
721:                         free(artData);
722:                         artData = NULL;
723:                     }
724:                     else if (artSize < 12
