771:             break;
772:         case 'X':
773:             rawEndian = 0;
774:             break;
775:         case 'v':
776:             verbose = atoi(optarg);
777:             break;
778:         case HELP_QUAL:
779:         case HELP_IO:
780:         case HELP_MP4:
781:         case HELP_ADVANCED:
782:         case 'H':
783:         case 'h':
784:             help(c);
785:             return 1;
786:             break;
787:         case OPT_JOINT:
788:             jointmode = atoi(optarg);
789:             break;
790:         case OPT_PNS:
791:             pnslevel = atoi(optarg);
792:             break;
793:         case '?':
