800: 
801:     /* check that we have at least one non-option arguments */
802:     if (!dieMessage && (argc - optind) > 1 && aacFileNameGiven)
803:         dieMessage =
804:             "Cannot encode several input files to one output file.\n";
805: 
806:     if (argc - optind < 1 || dieMessage)
807:     {
808:         fprintf(stderr, dieMessage, progName, progName, progName, progName);
809:         return 1;
810:     }
811: 
812:     while (argc - optind > 0)
813:     {
814:         /* get the input file name */
815:         audioFileName = argv[optind++];
816:     }
817: 
818:     /* generate the output file name, if necessary */
819:     if (!aacFileNameGiven)
820:     {
821:         char *t = strrchr(audioFileName, '.');
822:         int l = t ? strlen(audioFileName) - strlen(t) : strlen(audioFileName);
823: 
824:         aacFileExt = container == MP4_CONTAINER ? ".m4a" : ".aac";
825: 
826:         aacFileName = malloc(l + 1 + 4);
827:         if (!aacFileName)
828:         {
829:             fprintf(stderr, "out of memory\n");
830:             return 1;
831:         }
832:         memcpy(aacFileName, audioFileName, l);
833:         memcpy(aacFileName + l, aacFileExt, 4);
834:         aacFileName[l + 4] = '\0';
835:     }
836:     else
837:     {
838:         aacFileExt = strrchr(aacFileName, '.');
839: 
840:         if (aacFileExt
841:             && (!strcmp(".m4a", aacFileExt) || !strcmp(".m4b", aacFileExt)
842:                 || !strcmp(".mp4", aacFileExt)))
843:             container = MP4_CONTAINER;
844:     }
845: 
846:     /* open the audio input file */
847:     if (rawChans > 0)           // use raw input
848:     {
849:         infile = wav_open_read(audioFileName, 1);
850:         if (infile)
851:         {
852:             infile->bigendian = rawEndian;
853:             infile->channels = rawChans;
854:             infile->samplebytes = rawBits / 8;
855:             infile->samplerate = rawRate;
856:             infile->samples /= (infile->channels * infile->samplebytes);
857:         }
858:     }
859:     else                        // header input
860:         infile = wav_open_read(audioFileName, 0);
861: 
862:     if (infile == NULL)
863:     {
864:         fprintf(stderr, "Couldn't open input file %s\n", audioFileName);
865:         return 1;
866:     }
867: 
868:     if (container != MP4_CONTAINER && (ntracks || trackno || artist ||
869:                                        artistsort || title ||
870:                                        album || albumartist ||
871:                                        albumartistsort ||
872:                                        albumsort || year || artData ||
873:                                        genre || comment || discno || ndiscs ||
874:                                        composer || composersort ||
875:                                        compilation))
876:     {
877:         fprintf(stderr, "Metadata requires MP4 output!\n");
878:         return 1;
879:     }
880: 
881:     if (container == MP4_CONTAINER)
882:     {
883:         mpegVersion = FAAC_MPEG4;
884:         stream = FAAC_STREAM_RAW;
885:     }
886: 
887:     if (cutOff <= 0)
888:     {
889:         if (cutOff < 0)         // default
890:             cutOff = 0;
891:         else                    // disabled
892:             cutOff = infile->samplerate / 2;
893:     }
894:     if (cutOff > (infile->samplerate / 2))
895:         cutOff = infile->samplerate / 2;
