900:         fprintf(stderr, "disabling long blocks\n");
901:     }
902: 
903:     if (pnslevel > 0 && mpegVersion == FAAC_MPEG2)
904:     {
905:         fprintf(stderr, "PNS not allowed in MPEG-2 mode, disabling PNS\n");
906:         pnslevel = 0;
907:     }
