909:     /* put the options into the parameter struct and open the encoder */
910:     faac_params_init(&params);
911:     params.sample_rate   = infile->samplerate;
912:     params.num_channels  = infile->channels;
913:     params.mpeg_version  = mpegVersion;
914:     params.object_type   = objectType;
915:     params.joint_mode    = (jointmode >= 0) ? (enum faac_joint_mode)jointmode
916:                                             : params.joint_mode;
917:     params.use_lfe       = (infile->channels >= 6);
918:     params.use_tns       = useTns ? true : false;
919:     params.short_control = (enum faac_shortctl_mode)shortctl;
920:     if (pnslevel >= 0)
921:         params.pns_level = pnslevel;
922:     if (quantqual > 0)
923:     {
924:         params.quant_quality = quantqual;
925:         params.bit_rate = 0;
926:     }
927:     if (bitRate)
928:         params.bit_rate = bitRate / infile->channels;
929:     params.bandwidth     = cutOff;
930:     params.output_format = stream;
931:     params.input_format  = FAAC_INPUT_FLOAT;
932: 
933:     /* Reject too many channels with a specific message, rather than the generic
934:      * "invalid argument" that faac_encoder_open would otherwise return. */
935:     {
936:         faac_library_info libinfo = { .struct_size = sizeof(libinfo) };
937:         faac_get_library_info(&libinfo);
938:         if ((unsigned)infile->channels > libinfo.max_channels)
939:         {
940:             fprintf(stderr, "Input file %s has %u channels, but this build of "
941:                     "libfaac supports at most %u.\n",
942:                     audioFileName, (unsigned)infile->channels, libinfo.max_channels);
943:             wav_close(infile);
944:             return 1;
945:         }
946:     }
947: 
948:     fstatus = faac_encoder_open(&params, &hEncoder);
949:     if (fstatus != FAAC_OK)
950:     {
951:         fprintf(stderr, "Couldn't open encoder instance for input file %s: %s\n",
952:                 audioFileName, faac_strerror(fstatus));
953:         wav_close(infile);
954:         return 1;
955:     }
956: 
957:     /* buffer sizes and resolved settings come from the now-configured encoder */
958:     faac_encoder_info info;
959:     info.struct_size = sizeof(info);
960:     faac_encoder_get_info(hEncoder, &info);
961:     samplesInput   = (unsigned long)info.frame_samples * infile->channels;
962:     maxBytesOutput = info.max_output_bytes;
963:     frameSize = samplesInput / infile->channels;
964:     pcmbuf = (float *) malloc(samplesInput * sizeof(float));
965:     bitbuf = (unsigned char *) malloc(maxBytesOutput * sizeof(unsigned char));
966:     if (!pcmbuf || !bitbuf)
967:     {
968:         fprintf(stderr, "out of memory\n");
969:         return 1;
970:     }
971:     chanmap = mkChanMap(infile->channels, chanC, chanLF);
972:     if (chanmap)
973:     {
974:         fprintf(stderr, "Remapping input channels: Center=%d, LFE=%d\n",
975:                 chanC, chanLF);
976:     }
977: 
978:     /* AUTO may have resolved to LC or HE-AAC; read back the decision. */
979:     objectType = info.object_type;
980: 
981:     /* initialize MP4 creation */
982:     if (container == MP4_CONTAINER)
983:     {
984:         if (!strcmp(aacFileName, "-"))
985:         {
986:             fprintf(stderr, "cannot encode MP4 to stdout\n");
987:             return 1;
988:         }
989: 
990:         if (mp4_open(aacFileName, overwrite))
991:         {
992:             fprintf(stderr, "Couldn't create output file %s\n", aacFileName);
993:             return 1;
994:         }
995: 
996:         mp4_set_format(infile->samplerate, infile->channels, infile->samplebytes * 8);
997:     }
998:     else
999:     {
1000:         /* open the aac output file */
1001:         if (!strcmp(aacFileName, "-"))
1002:         {
1003:             outfile = stdout;
1004:         }
1005:         else
1006:         {
1007:             outfile = fopen(aacFileName, "wb");
1008:         }
1009:         if (!outfile)
1010:         {
1011:             fprintf(stderr, "Couldn't create output file %s\n", aacFileName);
1012:             return 1;
1013:         }
1014:     }
1015: 
1016:     /* report the effective settings the encoder resolved */
1017:     cutOff = info.bandwidth;
1018:     quantqual = info.quant_quality;
1019:     bitRate = info.bit_rate;
1020:     int resolvedPns = info.pns_level;
1021:     if (bitRate)
1022:     {
1023:         fprintf(stderr, "Initial quantization quality: %ld\n", quantqual);
1024:         fprintf(stderr, "Average bitrate: %d kbps/channel\n",
1025:                 (bitRate + 500) / 1000);
1026:     }
1027:     else
1028:         fprintf(stderr, "Quantization quality: %ld\n", quantqual);
1029:     fprintf(stderr, "Bandwidth: %d Hz\n", cutOff);
1030:     if (resolvedPns > 0)
1031:         fprintf(stderr, "PNS level: %d\n", resolvedPns);
1032:     fprintf(stderr, "Object type: %s",
1033:             (objectType == FAAC_OBJ_HE_AAC_V1) ? "HE-AAC v1" : "Low Complexity");
1034:     fprintf(stderr, " (MPEG-%d)", (mpegVersion == FAAC_MPEG4) ? 4 : 2);
1035:     if (params.use_tns)
1036:         fprintf(stderr, " + TNS");
1037: 
1038:     switch(params.joint_mode) {
1039:     case FAAC_JOINT_MS:
1040:         fprintf(stderr, " + M/S");
1041:         break;
1042:     case FAAC_JOINT_IS:
1043:         fprintf(stderr, " + IS");
1044:         break;
1045:     case FAAC_JOINT_MIXED:
1046:         fprintf(stderr, " + Mixed");
1047:         break;
1048:     default:
1049:         break;
1050:     }
1051:     if (resolvedPns > 0)
1052:         fprintf(stderr, " + PNS");
1053:     fprintf(stderr, "\n");
1054: 
1055:     fprintf(stderr, "Container format: ");
1056:     switch (container)
1057:     {
1058:     case NO_CONTAINER:
1059:         switch (stream)
1060:         {
1061:         case FAAC_STREAM_RAW:
1062:             fprintf(stderr, "Headerless AAC (RAW)\n");
1063:             break;
1064:         case FAAC_STREAM_ADTS:
1065:             fprintf(stderr, "Transport Stream (ADTS)\n");
1066:             break;
1067:         default:
1068:             break;
1069:         }
1070:         break;
1071:     case MP4_CONTAINER:
1072:         fprintf(stderr, "MPEG-4 File Format (MP4)\n");
1073:         break;
1074:     }
1075: 
1076:     int showcnt = 0;
1077: #ifdef _WIN32
1078:     long begin = GetTickCount();
1079: #endif
1080:     if (infile->samples)
1081:         frames = ((infile->samples + frameSize - 1) / frameSize) + 1;
1082:     else
1083:         frames = 0;
1084:     currentFrame = 0;
1085: 
1086:     fprintf(stderr, "Encoding %s to %s\n", audioFileName, aacFileName);
1087:     if (frames != 0)
1088:     {
1089:         fprintf(stderr, "         frame         | bitrate | elapsed/estim | "
1090:                 "play/CPU | ETA\n");
1091:     }
1092:     else
1093:     {
1094:         fprintf(stderr, "  frame  | elapsed | play/CPU\n");
1095:     }
1096: 
1097:     /* encoding loop */
1098: #ifdef _WIN32
1099:     for (;;)
1100: #else
1101:     while (running)
1102: #endif
1103:     {
1104:         int bytesWritten;
1105: 
1106:         if (!ignorelen)
1107:         {
1108:             if (input_samples < (uint64_t)infile->samples || infile->samples == 0)
1109:                 samplesRead =
1110:                     wav_read_float32(infile, pcmbuf, samplesInput, chanmap);
1111:             else
1112:                 samplesRead = 0;
1113: 
1114:             if (input_samples + (samplesRead / infile->channels) >
1115:                 (uint64_t)infile->samples && infile->samples != 0)
1116:                 samplesRead =
1117:                     (infile->samples - input_samples) * infile->channels;
1118:         }
1119:         else
1120:             samplesRead =
1121:                 wav_read_float32(infile, pcmbuf, samplesInput, chanmap);
1122: 
1123:         input_samples += samplesRead / infile->channels;
1124: 
1125:         /* call the actual encoding routine */
